solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

void appendSquares(std::vector<int>& v)
{
    const std::size_t original{ v.size() };
    v.reserve(original * 2);
    for (std::size_t i{ 0 }; i < original; ++i) v.push_back(v[i] * v[i]);
}

void duplicateEvens(std::vector<int>& v)
{
    std::vector<int> out;
    out.reserve(v.size() * 2);
    for (int x : v)
    {
        out.push_back(x);
        if (x % 2 == 0) out.push_back(x);
    }
    v.swap(out);
}

std::size_t removeNegatives(std::vector<int>& v)
{
    return std::erase_if(v, [](int x) { return x < 0; });
}

std::size_t removeShortKeys(std::map<std::string, int>& m, std::size_t minLength)
{
    std::size_t n{ 0 };
    for (auto it{ m.begin() }; it != m.end();)
    {
        if (it->first.size() < minLength)
        {
            it = m.erase(it);
            ++n;
        }
        else
        {
            ++it;
        }
    }
    return n;
}

unitTests:
TEST("appending squares of the original elements") {
    std::vector<int> v{ 1, 2, 3 };
    appendSquares(v);
    CHECK(v == (std::vector<int>{ 1, 2, 3, 1, 4, 9 }));
    std::vector<int> empty;
    appendSquares(empty);
    CHECK(empty.empty());
    std::vector<int> big(1000, 3);
    big.shrink_to_fit();
    appendSquares(big);
    CHECK_EQ(big.size(), 2000u);
    CHECK_EQ(big[999], 3);
    CHECK_EQ(big[1999], 9);
}
TEST("duplicating even elements") {
    std::vector<int> v{ 1, 2, 3, 4 };
    duplicateEvens(v);
    CHECK(v == (std::vector<int>{ 1, 2, 2, 3, 4, 4 }));
    std::vector<int> evens{ 2, 4, 6, 8, 10, 12, 14, 16 };
    evens.shrink_to_fit();
    duplicateEvens(evens);
    CHECK(evens == (std::vector<int>{ 2, 2, 4, 4, 6, 6, 8, 8, 10, 10, 12, 12, 14, 14, 16, 16 }));
    std::vector<int> odds{ 1, 3, -5 };
    duplicateEvens(odds);
    CHECK(odds == (std::vector<int>{ 1, 3, -5 }));
    std::vector<int> negative{ -2, 0 };
    duplicateEvens(negative);
    CHECK(negative == (std::vector<int>{ -2, -2, 0, 0 }));
}
TEST("removing negatives in order") {
    std::vector<int> v{ -1, 5, -2, -3, 7, 0, -9 };
    CHECK_EQ(removeNegatives(v), 4u);
    CHECK(v == (std::vector<int>{ 5, 7, 0 }));
    std::vector<int> all{ -1, -1 };
    CHECK_EQ(removeNegatives(all), 2u);
    CHECK(all.empty());
    CHECK_EQ(removeNegatives(all), 0u);
}
TEST("removing from a map while walking it") {
    std::map<std::string, int> m{ { "a", 1 }, { "bb", 2 }, { "c", 3 }, { "ddd", 4 }, { "e", 5 } };
    CHECK_EQ(removeShortKeys(m, 2), 3u);
    CHECK_EQ(m.size(), 2u);
    CHECK(m.count("bb") == 1 && m.count("ddd") == 1);
    CHECK_EQ(removeShortKeys(m, 10), 2u);
    CHECK(m.empty());
}

